window.renderAnnualPlayerRanking=block=>`<div class="annual-poster"><div class="annual-poster-heading"><span>RANKING MUNDIAL · BLOCK STRIKE</span><strong>TOP 20 <b>${block.year}</b></strong><small>Os jogadores que marcaram a temporada</small></div><ol class="annual-poster-grid" aria-label="Top 20 jogadores de ${block.year}">${[...block.entries].sort((a,b)=>a.rank-b.rank).map(entry=>{const H=window.HBSTV,name=H?.name(entry.name)||entry.name;return `<li class="annual-poster-card annual-place-${entry.rank}"><a href="${H?.playerHref(entry.name)||'#jogadores-todos'}" aria-label="${escapeHtml(name)}, posição ${entry.rank} em ${block.year}, Brasil, equipe ${escapeHtml(entry.team)}"><span class="annual-poster-rank">${entry.rank}</span><img src="assets/player-silhouette.svg" alt="" loading="lazy"><span class="annual-poster-player"><strong>${escapeHtml(name)}</strong><small><span aria-label="Brasil">🇧🇷</span> ${escapeHtml(entry.team)}</small></span></a></li>`}).join('')}</ol></div><p class="source-note">${escapeHtml(block.source)}</p>`;
